use vstd::prelude::*;

verus! {

    // Solve the “station‐refuel” problem:
    // a = total distance between endpoints
    // b = fuel capacity
    // f = station position from the start
    // k = number of end‐to‐end journeys
    //
    // Return:
    //   -1 if the itinerary is impossible under the given rules,
    //    0 if it is possible and no refueling is ever needed at the station,
    //    1 if it is possible and at least one refueling at the station is needed.
    //
    // Input assumptions:
    //   a > 0, b > 0, f > 0, f < a, k > 0
    //
    // Impossibility conditions:
    //   b < f
    //   b < a − f
    //   (k > 1 && b < 2·a − f)
    //   (k == 1 && b < a && b < f)
    //
    // Feasible ⇒ either b ≥ a  (no station needed) ⇒ return 0
    //           or b < a, b ≥ f  (station needed)     ⇒ return 1

    fn solve(a: i8, b: i8, f: i8, k: i8) -> (res: i8)
        requires
            a > 0,
            b > 0,
            f > 0,
            f < a,
            k > 0,
        ensures
            {
                // Lift to i16 to avoid overflow in expressions like 2·a − f
                let a16: i16 = a as i16;
                let b16: i16 = b as i16;
                let f16: i16 = f as i16;
                // Exactly characterise the impossible cases:
                (res == -1)
                    <==>
                    ( b16 < f16
                    || b16 < (a16 - f16)
                    || (k > 1 && b16 < (2*a16 - f16))
                    || (k == 1 && b16 < a16 && b16 < f16)
                    )
            },
        ensures
            // If not impossible, the result is 0 or 1
            res != -1 ==> (res == 0 || res == 1),
        ensures
            {
                let a16: i16 = a as i16;
                let b16: i16 = b as i16;
                // No‐refuel ↔ capacity ≥ total distance
                res != -1 ==> (res == 0) <==> (b16 >= a16)
            },
        ensures
            {
                let a16: i16 = a as i16;
                let b16: i16 = b as i16;
                let f16: i16 = f as i16;
                // Must‐refuel ↔ capacity < total distance ∧ capacity ≥ station distance
                res != -1 ==> (res == 1) <==> (b16 < a16 && b16 >= f16)
            },
    {
        // At runtime we do the same checks, casting to 16 bits
        let a16: i16 = a as i16;
        let b16: i16 = b as i16;
        let f16: i16 = f as i16;

        if b16 < f16
           || b16 < (a16 - f16)
           || (k > 1 && b16 < (2*a16 - f16))
           || (k == 1 && b16 < a16 && b16 < f16)
        {
            return -1;
        }

        // Feasible case:
        if b16 >= a16 {
            0
        } else {
            1
        }
    }
}

